CREATE FUNCTION public.panda_agent_composite_tools_read() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE result jsonb;BEGIN
 PERFORM public.panda_agent_skill_admin();
 SELECT jsonb_build_object('tools',coalesce(jsonb_agg(jsonb_build_object('id',t.id,'enabled',t.enabled,'version',t.version,'manifest',t.manifest,'hash',t.manifest_hash,'health','not_checked','history',(SELECT coalesce(jsonb_agg(jsonb_build_object('enabled',e.enabled,'reason',e.reason,'at',e.at) ORDER BY e.at DESC,e.id DESC),'[]') FROM (SELECT * FROM public.panda_agent_tool_events WHERE tool_id=t.id ORDER BY at DESC,id DESC LIMIT 20) e)) ORDER BY t.id),'[]')) INTO result FROM public.panda_agent_tools t WHERE t.id IN ('panda_scoped_rag','fetch_public_docs_mcp','convert_units','format_bom');
 RETURN result;
END $$;
CREATE FUNCTION public.panda_agent_composite_tool_change(p_input jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 PERFORM public.panda_agent_skill_admin();
 IF p_input->>'toolId' NOT IN ('panda_scoped_rag','fetch_public_docs_mcp','convert_units','format_bom') THEN PERFORM public.phase3_fail('invalid');END IF;
 PERFORM public.panda_agent_tool_change(p_input);
 RETURN public.panda_agent_composite_tools_read();
END $$;
REVOKE ALL ON FUNCTION public.panda_agent_composite_tools_read(),public.panda_agent_composite_tool_change(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.panda_agent_composite_tools_read(),public.panda_agent_composite_tool_change(jsonb) TO authenticated;
